/**
 * OWidgetFrame v4 — 极简版
 *
 * 锁定态:右上角悬停浮现单个 ○ 按钮 → 点击解锁
 * 解锁态:右上角浮动工具条 [● − + ✕]
 *   ● 收回锁定   − 缩小   + 放大   ✕ 关闭(弹确认 → 隐藏,后台保留可调回)
 *
 * 拖动:解锁态下,标题区域(整个 frame 顶部)可拖动移位
 * 缩放:解锁态右下角 resize 手柄
 */
'use client';

import {
  forwardRef,
  useCallback,
  useState,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
} from 'react';
import { useWidgetContext } from './WidgetContext';

export interface OWidgetFrameProps {
  id: string;
  title?: string;
  locked: boolean;
  onLockToggle: (id: string) => void;
  zoom: number;
  colSpan: number;
  rowSpan: number;
  onZoomChange?: (id: string, zoom: number) => void;
  onClose?: (id: string) => void;
  /** 关闭确认文案,默认"确认关闭吗?" */
  closeConfirmText?: string;
  children: ReactNode;
  className?: string;
}

const ZOOM_STEPS = [0.5, 0.67, 0.8, 1, 1.25, 1.5, 2];

export const OWidgetFrame = forwardRef<HTMLDivElement, OWidgetFrameProps>(
  function OWidgetFrame(
    {
      id, title, locked, onLockToggle, zoom, colSpan, rowSpan,
      onZoomChange, onClose, closeConfirmText = '确认关闭吗?',
      children, className,
    },
    ref
  ) {
    const { onDragStart, onResizeStart } = useWidgetContext();
    const [confirmingClose, setConfirmingClose] = useState(false);

    const zoomIn = useCallback(() => {
      const next = ZOOM_STEPS.find(z => z > zoom) ?? ZOOM_STEPS[ZOOM_STEPS.length - 1]!;
      onZoomChange?.(id, next as number);
    }, [id, zoom, onZoomChange]);

    const zoomOut = useCallback(() => {
      const next = [...ZOOM_STEPS].reverse().find(z => z < zoom) ?? ZOOM_STEPS[0]!;
      onZoomChange?.(id, next as number);
    }, [id, zoom, onZoomChange]);

    const handleDragStart = useCallback((e: ReactPointerEvent) => {
      if (locked) return;
      e.currentTarget.setPointerCapture(e.pointerId);
      onDragStart(id, e.nativeEvent);
    }, [id, locked, onDragStart]);

    const handleResizeStart = useCallback((e: ReactPointerEvent) => {
      if (locked) return;
      e.stopPropagation();
      e.currentTarget.setPointerCapture(e.pointerId);
      onResizeStart(id, e.nativeEvent);
    }, [id, locked, onResizeStart]);

    return (
      <div
        ref={ref}
        className={[
          'oui-widget-frame',
          locked ? 'oui-widget-frame--locked' : 'oui-widget-frame--unlocked',
          className ?? '',
        ].join(' ')}
        data-id={id}
      >
        {/* ── 右上角浮动工具条 ── */}
        {locked && <div className="oui-widget-hotzone" aria-hidden />}
        <div className="oui-widget-tools">
          {locked ? (
            /* 锁定:单个 ○ 按钮,hover 浮现,点击解锁 */
            <button
              type="button"
              className="oui-widget-tool-btn oui-widget-state-btn"
              onClick={() => onLockToggle(id)}
              aria-label="解锁(可移动/缩放)"
              title="解锁"
            >○</button>
          ) : (
            /* 解锁:● − + ✕ */
            <>
              <button type="button" className="oui-widget-tool-btn oui-widget-state-btn oui-widget-state-btn--active"
                onClick={() => onLockToggle(id)} aria-label="锁定" title="锁定">●</button>
              <button type="button" className="oui-widget-tool-btn"
                onClick={zoomOut} disabled={zoom <= (ZOOM_STEPS[0] ?? 0.5)}
                aria-label="缩小" title="缩小">−</button>
              <button type="button" className="oui-widget-tool-btn"
                onClick={zoomIn} disabled={zoom >= (ZOOM_STEPS[ZOOM_STEPS.length - 1] ?? 2)}
                aria-label="放大" title="放大">+</button>
              {onClose && (
                <button type="button" className="oui-widget-tool-btn oui-widget-close-btn"
                  onClick={() => setConfirmingClose(true)} aria-label="关闭" title="关闭">✕</button>
              )}
            </>
          )}
        </div>

        {/* ── 解锁态:顶部拖动区(整条,无把手图标) ── */}
        {!locked && (
          <div className="oui-widget-draghandle" onPointerDown={handleDragStart} aria-label="拖动移动">
            {title && <span className="oui-widget-title">{title}</span>}
          </div>
        )}

        {/* ── 锁定态:轻量标题 ── */}
        {locked && title && (
          <div className="oui-widget-titlebar--locked">
            <span className="oui-widget-title">{title}</span>
          </div>
        )}

        {/* ── 内容区 ── */}
        <div className="oui-widget-content">
          <div
            className="oui-widget-content-inner"
            style={{
              transform: zoom !== 1 ? `scale(${zoom})` : undefined,
              transformOrigin: 'top left',
              width:  zoom !== 1 ? `${100 / zoom}%` : undefined,
              height: zoom !== 1 ? `${100 / zoom}%` : undefined,
            }}
          >
            {children}
          </div>
        </div>

        {/* ── 解锁态右下角 resize ── */}
        {!locked && (
          <div className="oui-widget-resize-handle" onPointerDown={handleResizeStart}
            aria-label="拖动调整大小" role="separator" />
        )}

        {/* ── 关闭确认 ── */}
        {confirmingClose && (
          <div className="oui-widget-confirm" role="alertdialog" aria-label="关闭确认">
            <div className="oui-widget-confirm__box">
              <p className="oui-widget-confirm__text">{closeConfirmText}</p>
              <p className="oui-widget-confirm__hint">关闭后可随时从面板调回</p>
              <div className="oui-widget-confirm__actions">
                <button type="button" className="oui-widget-confirm__btn"
                  onClick={() => setConfirmingClose(false)}>取消</button>
                <button type="button" className="oui-widget-confirm__btn oui-widget-confirm__btn--danger"
                  onClick={() => { setConfirmingClose(false); onClose?.(id); }}>关闭</button>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }
);

OWidgetFrame.displayName = 'OWidgetFrame';
