/**
 * OWidgetGrid — Dashboard 网格容器
 *
 * 通过 WidgetContext 向子 OWidgetFrame 注入:
 *   locked / onDragStart / onResizeStart / onLockToggle
 *
 * 用法:
 *   const { locked, setLocked, widgets, updateWidget, resetLayout } = useWidgetStorage({...});
 *
 *   <OWidgetGrid
 *     locked={locked}
 *     onLockToggle={() => setLocked(!locked)}
 *     widgets={widgets}
 *     onWidgetChange={updateWidget}
 *     gridCols={12}
 *     rowHeight={80}
 *   >
 *     {({ id, layout }) => (
 *       <OWidgetFrame key={id} id={id} title="KPI" zoom={layout.zoom}
 *         colSpan={layout.colSpan} rowSpan={layout.rowSpan}
 *         onZoomChange={(id, z) => updateWidget(id, { zoom: z })}
 *         onClose={(id) => updateWidget(id, { visible: false })}
 *       >
 *         <OKPICard ... />
 *       </OWidgetFrame>
 *     )}
 *   </OWidgetGrid>
 */
'use client';

import React, {
  useCallback, useEffect, useMemo, useRef, useState,
  type ReactNode,
} from 'react';
import type { WidgetLayout } from './types';
import { WidgetContext } from './WidgetContext';

export interface OWidgetGridProps {
  widgets: Record<string, WidgetLayout>;
  onWidgetChange: (id: string, patch: Partial<WidgetLayout>) => void;
  gridCols?: number;
  rowHeight?: number;
  gap?: number;
  children: (item: { id: string; layout: WidgetLayout }) => ReactNode;
  className?: string;
}

interface DragState {
  type: 'move' | 'resize';
  id: string;
  offsetX: number;
  offsetY: number;
  startColSpan: number;
  startRowSpan: number;
  startX: number;
  startY: number;
}

export function OWidgetGrid({
  widgets,
  onWidgetChange,
  gridCols = 12,
  rowHeight = 80,
  gap = 8,
  children,
  className,
}: OWidgetGridProps) {
  const gridRef   = useRef<HTMLDivElement>(null);
  const dragState = useRef<DragState | null>(null);
  const [ghost, setGhost] = useState<{
    id: string; col: number; row: number; colSpan: number; rowSpan: number;
  } | null>(null);

  // ── 坐标换算 ─────────────────────────────────────
  const pxToCol = useCallback((relX: number, totalW: number) => {
    const cellW = (totalW - gap * (gridCols - 1)) / gridCols;
    return Math.max(1, Math.floor(relX / (cellW + gap)) + 1);
  }, [gridCols, gap]);

  const pxToRow = useCallback((relY: number) => {
    return Math.max(1, Math.floor(relY / (rowHeight + gap)) + 1);
  }, [rowHeight, gap]);

  // ── drag/resize start(由 OWidgetFrame 通过 Context 回调) ──
  const onDragStart = useCallback((id: string, e: PointerEvent) => {
    const grid = gridRef.current;
    const lay0 = widgets[id];
    if (!grid || !lay0 || lay0.locked) return;
    const rect   = grid.getBoundingClientRect();
    const layout = widgets[id];
    if (!layout) return;
    dragState.current = {
      type: 'move', id,
      offsetX: e.clientX - rect.left,
      offsetY: e.clientY - rect.top,
      startColSpan: layout.colSpan,
      startRowSpan: layout.rowSpan,
      startX: e.clientX,
      startY: e.clientY,
    };
    setGhost({ id, col: layout.col, row: layout.row, colSpan: layout.colSpan, rowSpan: layout.rowSpan });
  }, [widgets]);

  const onResizeStart = useCallback((id: string, e: PointerEvent) => {
    const layout = widgets[id];
    if (!layout || layout.locked) return;
    dragState.current = {
      type: 'resize', id,
      offsetX: 0, offsetY: 0,
      startColSpan: layout.colSpan,
      startRowSpan: layout.rowSpan,
      startX: e.clientX,
      startY: e.clientY,
    };
    setGhost({ id, col: layout.col, row: layout.row, colSpan: layout.colSpan, rowSpan: layout.rowSpan });
  }, [widgets]);

  // ── Pointer move ─────────────────────────────────
  const onPointerMove = useCallback((e: PointerEvent) => {
    const ds   = dragState.current;
    const grid = gridRef.current;
    if (!ds || !grid) return;

    const rect   = grid.getBoundingClientRect();
    const layout = widgets[ds.id];
    if (!layout) return;

    if (ds.type === 'move') {
      const relX  = e.clientX - rect.left - (ds.offsetX - rect.left);
      const relY  = e.clientY - rect.top  - (ds.offsetY - rect.top);
      const col   = Math.max(1, Math.min(gridCols - layout.colSpan + 1, pxToCol(e.clientX - rect.left, rect.width)));
      const row   = Math.max(1, pxToRow(e.clientY - rect.top));
      setGhost(g => g ? { ...g, col, row } : g);

    } else {
      const dx = e.clientX - ds.startX;
      const dy = e.clientY - ds.startY;
      const cellW = (rect.width - gap * (gridCols - 1)) / gridCols;
      const dCols = Math.round(dx / (cellW + gap));
      const dRows = Math.round(dy / (rowHeight + gap));
      const colSpan = Math.max(1, Math.min(gridCols - layout.col + 1, ds.startColSpan + dCols));
      const rowSpan = Math.max(1, ds.startRowSpan + dRows);
      setGhost(g => g ? { ...g, colSpan, rowSpan } : g);
    }
  }, [widgets, gridCols, gap, rowHeight, pxToCol, pxToRow]);

  // ── Pointer up — commit ──────────────────────────
  const onPointerUp = useCallback(() => {
    const ds = dragState.current;
    if (ds && ghost) {
      onWidgetChange(ds.id, {
        col:     ghost.col,
        row:     ghost.row,
        colSpan: ghost.colSpan,
        rowSpan: ghost.rowSpan,
      });
    }
    dragState.current = null;
    setGhost(null);
  }, [ghost, onWidgetChange]);

  useEffect(() => {
    window.addEventListener('pointermove', onPointerMove);
    window.addEventListener('pointerup',   onPointerUp);
    return () => {
      window.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('pointerup',   onPointerUp);
    };
  }, [onPointerMove, onPointerUp]);

  // ── Context value ────────────────────────────────
  const ctxValue = useMemo(() => ({
    onDragStart, onResizeStart,
  }), [onDragStart, onResizeStart]);

  // ── 可见 widgets ─────────────────────────────────
  const visibleEntries = useMemo(
    () => Object.values(widgets).filter(w => w.visible),
    [widgets]
  );

  const totalRows = useMemo(() => {
    let max = 4;
    for (const w of visibleEntries) max = Math.max(max, w.row + w.rowSpan - 1);
    return max + 2;
  }, [visibleEntries]);

  // 有任意框解锁 → 显示网格线辅助
  const anyUnlocked = useMemo(
    () => visibleEntries.some(w => !w.locked),
    [visibleEntries]
  );

  return (
    <WidgetContext.Provider value={ctxValue}>
      <div
        ref={gridRef}
        className={[
          'oui-widget-grid',
          anyUnlocked ? 'oui-widget-grid--editing' : '',
          className ?? '',
        ].join(' ')}
        style={{
          '--oui-grid-cols':  gridCols,
          '--oui-row-height': `${rowHeight}px`,
          '--oui-grid-gap':   `${gap}px`,
          '--oui-total-rows': totalRows,
        } as React.CSSProperties}
      >
        {/* Ghost 占位 */}
        {ghost && (
          <div
            className="oui-widget-ghost"
            aria-hidden
            style={{
              gridColumn: `${ghost.col} / span ${ghost.colSpan}`,
              gridRow:    `${ghost.row} / span ${ghost.rowSpan}`,
            }}
          />
        )}

        {/* Widgets */}
        {visibleEntries.map(layout => (
          <div
            key={layout.id}
            className={[
              'oui-widget-cell',
              ghost?.id === layout.id ? 'oui-widget-cell--dragging' : '',
            ].join(' ')}
            style={{
              gridColumn: `${layout.col} / span ${layout.colSpan}`,
              gridRow:    `${layout.row} / span ${layout.rowSpan}`,
              contentVisibility: 'auto',
            }}
          >
            {children({ id: layout.id, layout })}
          </div>
        ))}
      </div>
    </WidgetContext.Provider>
  );
}
